def merge(intervals):
    """Merge overlapping or touching [start, end] intervals.

    The input list and its interval lists are not changed.  The returned
    intervals are new lists, sorted by start value, with no overlaps or
    touching ends.
    """
    if not intervals:
        return []

    ordered = sorted((list(interval) for interval in intervals),
                     key=lambda interval: interval[0])

    merged = [ordered[0][:]]
    for start, end in ordered[1:]:
        last_start, last_end = merged[-1]
        if start <= last_end:
            if end > last_end:
                merged[-1][1] = end
        else:
            merged.append([start, end])

    return merged
